import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-06-11","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-06-11","date":"2025-06-11T00:00:00.000Z","updated":"2025-06-23T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","加密","多站点复制","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-06-11.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-06-11.md","lastUpdated":1780460162000}'),o={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-06-11.md"};function r(n,e,s,p,c,_){return t(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="ceph-rgw-重构会议纪要-2025-06-11" tabindex="-1">Ceph RGW 重构会议纪要 2025-06-11 <a class="header-anchor" href="#ceph-rgw-重构会议纪要-2025-06-11" aria-label="Permalink to &quot;Ceph RGW 重构会议纪要 2025-06-11&quot;">​</a></h3><p><strong>日期</strong>：2025-06-11 <strong>参会人员</strong>：Cena、Marcus、Casey、Shelpa（未出席但涉及议题）等</p><h4 id="主要议题与讨论" tabindex="-1">主要议题与讨论 <a class="header-anchor" href="#主要议题与讨论" aria-label="Permalink to &quot;主要议题与讨论&quot;">​</a></h4><ol><li><p><strong>跨区域组复制（Cross-Zone Group Replication）设计规划</strong></p><ul><li>Cena 已提交初步设计草案，但存在未解决的开放性问题，需团队共识后拆分任务并排期。</li><li>决定通过 RGW Devel 频道异步讨论，并需编写详细设计文档（Design Doc）。</li></ul></li><li><p><strong>加密对象复制（Copy Encrypted Objects）的PR选择</strong></p><ul><li>Marcus 和 Cena 的 PR 对比分析，包括代码结构、测试覆盖等方面。</li><li>决策：优先合并 Marcus PR（因已有下游验证），后续由 Cena 在其基础上优化代码结构。</li></ul></li><li><p><strong>多站点复制（Multi-Site Replication）的未决问题</strong></p><ul><li>多部分对象复制后的加密一致性测试。</li><li>需补充以下场景的自动化测试：跨集群复制、同集群多区域复制、多部分对象复制。</li></ul></li><li><p><strong>Tentacle 发布计划</strong></p><ul><li>首个RC版本已启动测试，但部分关键功能未合并。</li><li>决策：Marcus 将推进CI构建，Casey 协助补充多站点测试用例。</li></ul></li></ol><h4 id="行动计划与责任人" tabindex="-1">行动计划与责任人 <a class="header-anchor" href="#行动计划与责任人" aria-label="Permalink to &quot;行动计划与责任人&quot;">​</a></h4><p>| 任务 | 责任人 | 时间节点 | ||--|-| | 提交跨区域复制设计文档 | Cena &amp; Shelpa | 下周 | | 修复 Marcus PR 的CI构建问题 | Marcus | 本周 | | 扩展多站点复制测试用例（集成Vault） | Casey &amp; Cena | RC测试阶段 | | 评审并合并 Somia的<code>restore object</code> PR | Casey | 本周 | | 补充多部分对象复制的S3测试 | Cena | 本周 |</p><h4 id="遗留问题" tabindex="-1">遗留问题 <a class="header-anchor" href="#遗留问题" aria-label="Permalink to &quot;遗留问题&quot;">​</a></h4><ul><li>多站点复制密钥管理。</li><li><code>copy object</code> 路径中是否需避免不必要的解压/压缩。</li></ul><p><strong>下次会议重点</strong>：Review CI测试结果与多站点复制测试进展。</p><p>会议全程英文进行，部分技术术语保留原词（如PR、SSE-S3、Vault等）以确保准确性。</p>',10)])])}const d=a(o,[["render",r]]);export{u as __pageData,d as default};
